import { describe, expect, it } from "vitest";

import {
	parseHookIngestRequest,
	parseTaskSessionStartRequest,
	parseWorkspaceFileSearchRequest,
} from "../../src/core/api-validation";

describe("parseWorkspaceFileSearchRequest", () => {
	it("parses q and limit", () => {
		const parsed = parseWorkspaceFileSearchRequest(new URLSearchParams({ q: "  src/runtime ", limit: "25" }));
		expect(parsed).toEqual({
			query: "src/runtime",
			limit: 25,
		});
	});

	it("treats missing q as empty query", () => {
		const parsed = parseWorkspaceFileSearchRequest(new URLSearchParams({ limit: "10" }));
		expect(parsed).toEqual({
			query: "",
		});
	});

	it("does not accept legacy query alias", () => {
		const parsed = parseWorkspaceFileSearchRequest(new URLSearchParams({ query: "legacy" }));
		expect(parsed).toEqual({
			query: "",
		});
	});

	it("throws when limit is invalid", () => {
		expect(() => {
			parseWorkspaceFileSearchRequest(new URLSearchParams({ q: "board", limit: "0" }));
		}).toThrow("Invalid file search limit parameter.");
	});
});

describe("parseHookIngestRequest", () => {
	it("parses and trims task and workspace identifiers", () => {
		const parsed = parseHookIngestRequest({
			taskId: "  task-123  ",
			workspaceId: "  workspace-456  ",
			event: "to_review",
			metadata: {
				source: " claude ",
				activityText: " Using Read ",
			},
		});
		expect(parsed).toEqual({
			taskId: "task-123",
			workspaceId: "workspace-456",
			event: "to_review",
			metadata: {
				source: "claude",
				activityText: "Using Read",
				hookEventName: undefined,
				toolName: undefined,
				finalMessage: undefined,
				notificationType: undefined,
			},
		});
	});

	it("throws when workspaceId is missing", () => {
		expect(() => {
			parseHookIngestRequest({
				taskId: "task-1",
				workspaceId: "   ",
				event: "to_review",
			});
		}).toThrow("Missing workspaceId");
	});
});

describe("parseTaskSessionStartRequest", () => {
	it("parses resumeFromTrash and trims task identifiers", () => {
		const parsed = parseTaskSessionStartRequest({
			taskId: "  task-1  ",
			prompt: "",
			baseRef: "  main  ",
			resumeFromTrash: true,
		});
		expect(parsed).toEqual({
			taskId: "task-1",
			prompt: "",
			baseRef: "main",
			resumeFromTrash: true,
		});
	});
});

import {
	type ClineSdkToolApprovalRequest,
	type ClineSdkToolApprovalResult,
	type ClineSdkUserInstructionService,
	createClineSdkUserInstructionService,
	loadClineSdkRulesForSystemPrompt,
	resolveClineSdkWorkflowSlashCommand,
} from "./sdk-runtime-boundary";

export interface ClineRuntimeSetup {
	userInstructionService: ClineSdkUserInstructionService;
	resolvePrompt: (prompt: string) => string;
	loadRules: () => string;
	requestToolApproval: (request: ClineSdkToolApprovalRequest) => Promise<ClineSdkToolApprovalResult>;
	dispose: () => Promise<void>;
}

export async function createClineRuntimeSetup(workspacePath: string): Promise<ClineRuntimeSetup> {
	const userInstructionService = createClineSdkUserInstructionService(workspacePath);
	try {
		await userInstructionService.start();
	} catch {}

	return {
		userInstructionService,
		resolvePrompt: (prompt: string) => resolveClineSdkWorkflowSlashCommand(prompt, userInstructionService),
		loadRules: () => loadClineSdkRulesForSystemPrompt(userInstructionService),
		requestToolApproval: async (request: ClineSdkToolApprovalRequest) => ({
			approved: true,
			reason: `Approved by Kanban runtime for ${request.toolName}.`,
		}),
		dispose: async () => {
			try {
				userInstructionService.stop();
			} catch {}
		},
	};
}

import type { ClineSdkPersistedMessage } from "./sdk-runtime-boundary";

/**
 * Temporary Kanban-side fallback for context overflow recovery.
 * TODO: remove this once SDK-side pluggable compaction policies are available and wired through Kanban.
 */
const CONTEXT_OVERFLOW_ERROR_PATTERNS = [
	/prompt is too long/i,
	/prompt is too long.*tokens?\s*>\s*\d+\s*maximum/i,
	/maximum prompt length/i,
	/input is too long/i,
	/context length exceeded/i,
	/context length.*exceeds/i,
	/maximum context length/i,
	/\bcontext\s*(?:length|window)\b/i,
	/\bcontext\s*(?:length|window)\b.*exceed/i,
	/\bmaximum\s*context\b/i,
	/context window.*(exceed|limit|too)/i,
	/(exceed|exceeds|exceeded).*context window/i,
	/input exceeds.*context window/i,
	/too many tokens/i,
	/\btoo\s*many\s*tokens?\b/i,
	/\b(?:input\s*)?tokens?\s*exceed/i,
	/maximum tokens.*exceeds.*model limit/i,
	/input length and max_tokens exceed context limit/i,
	/total number of tokens.*exceeds.*limit/i,
	/requested.*tokens.*exceeds.*limit/i,
	/requested input length.*exceeds.*maximum input length/i,
	/input token count exceeds.*maximum.*tokens? allowed/i,
	/reduce.*length.*messages.*completion/i,
	/tokens?\s*>\s*[\d,]+\s*(maximum|limit)/i,
	/input tokens?.*(exceed|exceeds).*(limit|maximum|context)/i,
];
const CONTEXT_COMPACTION_PREVIEW_CHARS = 300;

export function isContextOverflowError(error: unknown): boolean {
	if (!(error instanceof Error)) {
		return false;
	}
	return CONTEXT_OVERFLOW_ERROR_PATTERNS.some((pattern) => pattern.test(error.message));
}

function readMessagePreview(message: ClineSdkPersistedMessage): string {
	const rawText =
		typeof message.content === "string"
			? message.content
			: message.content
					.map((block) => {
						if (block.type === "text") {
							return block.text;
						}
						if (block.type === "file") {
							return block.path;
						}
						if (block.type === "tool_use") {
							return `${block.name} ${JSON.stringify(block.input)}`;
						}
						if (block.type === "tool_result") {
							return typeof block.content === "string" ? block.content : "[tool_result]";
						}
						if (block.type === "thinking") {
							return block.thinking;
						}
						if (block.type === "redacted_thinking") {
							return "[redacted_thinking]";
						}
						return "[image]";
					})
					.join(" ");

	const normalized = rawText.replace(/\s+/g, " ").trim();
	if (!normalized) {
		return "(empty)";
	}
	if (normalized.length <= CONTEXT_COMPACTION_PREVIEW_CHARS) {
		return normalized;
	}
	return `${normalized.slice(0, CONTEXT_COMPACTION_PREVIEW_CHARS)}...`;
}

function prependCompactionNotice(
	message: ClineSdkPersistedMessage,
	firstUserMessage: string,
): ClineSdkPersistedMessage {
	const note = `[Previous conversation history was removed due to context window limits. Infer prior actions from the current environment state. First user message from the removed history: ${firstUserMessage}]`;
	if (typeof message.content === "string") {
		return {
			...message,
			content: `${note}\n\n${message.content}`,
		};
	}
	return {
		...message,
		content: [{ type: "text", text: note }, ...message.content],
	};
}

export function compactPersistedMessagesForContextOverflow(
	messages: ClineSdkPersistedMessage[],
): ClineSdkPersistedMessage[] | null {
	if (messages.length < 2) {
		return null;
	}

	const firstUserMessage = messages.find((message) => message.role === "user");
	if (!firstUserMessage) {
		return null;
	}
	const firstUserMessagePreview = readMessagePreview(firstUserMessage);

	let retained = messages.slice(Math.floor(messages.length / 2));
	while (retained.length > 0 && retained[0]?.role !== "user") {
		retained = retained.slice(1);
	}
	if (retained.length === 0) {
		return null;
	}

	const rewrittenFirstMessage = prependCompactionNotice(retained[0], firstUserMessagePreview);
	const compactedMessages = [rewrittenFirstMessage, ...retained.slice(1)];
	if (compactedMessages.length >= messages.length) {
		return null;
	}
	return compactedMessages;
}

// Node.js v22+ adds a built-in localStorage to globalThis that lacks
// Web Storage API methods when --localstorage-file is not provided.
// This conflicts with jsdom's proper implementation because vitest's
// populateGlobal() skips keys that already exist on globalThis.
// Replace the broken stub with a spec-compliant in-memory Storage mock.
const hasWorkingLocalStorage = (): boolean => {
	try {
		const storage = globalThis.localStorage as Partial<Storage> | undefined;
		return Boolean(
			storage &&
				typeof storage.getItem === "function" &&
				typeof storage.setItem === "function" &&
				typeof storage.removeItem === "function" &&
				typeof storage.clear === "function" &&
				typeof storage.key === "function",
		);
	} catch {
		return false;
	}
};

if (!hasWorkingLocalStorage()) {
	const store = new Map<string, string>();
	const storage: Storage = {
		getItem: (key: string) => store.get(key) ?? null,
		setItem: (key: string, value: string) => {
			store.set(key, String(value));
		},
		removeItem: (key: string) => {
			store.delete(key);
		},
		clear: () => {
			store.clear();
		},
		get length() {
			return store.size;
		},
		key: (index: number) => [...store.keys()][index] ?? null,
	};
	Object.defineProperty(globalThis, "localStorage", {
		value: storage,
		writable: true,
		configurable: true,
	});
}

class MockIntersectionObserver implements IntersectionObserver {
	readonly root: Element | Document | null = null;
	readonly rootMargin = "";
	readonly thresholds = [0];

	disconnect(): void {}

	observe(_target: Element): void {}

	takeRecords(): IntersectionObserverEntry[] {
		return [];
	}

	unobserve(_target: Element): void {}
}

Object.defineProperty(globalThis, "IntersectionObserver", {
	writable: true,
	configurable: true,
	value: MockIntersectionObserver,
});

// jsdom does not implement window.matchMedia. Provide a minimal stub so that
// hooks like useIsMobile and react-use's useMedia work during tests.
if (typeof window !== "undefined" && typeof window.matchMedia !== "function") {
	Object.defineProperty(window, "matchMedia", {
		writable: true,
		configurable: true,
		value: (query: string): MediaQueryList => ({
			matches: false,
			media: query,
			onchange: null,
			addListener: () => {},
			removeListener: () => {},
			addEventListener: () => {},
			removeEventListener: () => {},
			dispatchEvent: () => false,
		}),
	});
}

import { describe, expect, it } from "vitest";

import {
	applyClineComposerCompletion,
	buildMentionInsertText,
	buildSlashCommandInsertText,
	detectActiveClineComposerToken,
} from "@/components/detail-panels/cline-chat-composer-completion";

describe("cline-chat-composer-completion", () => {
	it("detects active mention tokens at the cursor", () => {
		expect(detectActiveClineComposerToken("Review @src/comp", "Review @src/comp".length)).toEqual({
			kind: "mention",
			start: 7,
			end: 16,
			query: "src/comp",
		});
	});

	it("detects active slash tokens at the start of the draft", () => {
		expect(detectActiveClineComposerToken("/con", 4)).toEqual({
			kind: "slash",
			start: 0,
			end: 4,
			query: "con",
		});
	});

	it("ignores inline markers that are not token boundaries", () => {
		expect(detectActiveClineComposerToken("foo/bar", "foo/bar".length)).toBeNull();
		expect(detectActiveClineComposerToken("mail@test", "mail@test".length)).toBeNull();
	});

	it("formats mention insert text with quotes when needed", () => {
		expect(buildMentionInsertText("src/app.ts")).toBe("@/src/app.ts");
		expect(buildMentionInsertText("docs/my file.md")).toBe('@"/docs/my file.md"');
	});

	it("formats slash command insert text", () => {
		expect(buildSlashCommandInsertText("config")).toBe("/config");
	});

	it("applies a completion and preserves trailing content", () => {
		const token = detectActiveClineComposerToken("/con next", 4);
		expect(token).not.toBeNull();
		const next = applyClineComposerCompletion("/con next", token!, "/config");
		expect(next).toEqual({
			value: "/config next",
			cursor: 7,
		});
	});
});

import { act, useEffect } from "react";
import { createRoot, type Root } from "react-dom/client";
