		expect(startBacklogTaskWithAnimation.mock.calls[1]?.[0]).toMatchObject({ id: "task-3" });

		await act(async () => {
			firstKickoff.resolve(true);
			secondKickoff.resolve(true);
			await movePromise;
		});

		expect(trackTasksAutoStartedFromDependencyMock).toHaveBeenCalledWith(2);
	});
});

