/**
 * Unit tests for the internal CLI auth token mechanism in passcode-manager.ts.
 */

import { afterEach, describe, expect, it, vi } from "vitest";
import {
	disablePasscode,
	extractBearerToken,
	extractSessionTokenFromCookie,
	generateInternalToken,
	generatePasscode,
	getInternalToken,
	INTERNAL_TOKEN_ENV,
	isPasscodeEnabled,
	issueSession,
	validateInternalToken,
	validatePasscode,
	validateSession,
} from "../../../src/security/passcode-manager";

function runHttpGate(input: {
	isRemoteMode: boolean;
	cookieHeader: string | undefined;
	authorizationHeader: string | undefined;
	pathname: string;
}): "allowed" | "rejected" {
	const passcodeActive = input.isRemoteMode && isPasscodeEnabled();
	if (passcodeActive) {
		const sessionToken = extractSessionTokenFromCookie(input.cookieHeader);
		const sessionAuth = sessionToken !== null && validateSession(sessionToken);
		const bearerToken = extractBearerToken(input.authorizationHeader);
		const internalAuth = bearerToken !== null && validateInternalToken(bearerToken);
		if (!(sessionAuth || internalAuth) && input.pathname.startsWith("/api/")) {
			return "rejected";
		}
	}
	return "allowed";
}

function runWsUpgradeGate(input: {
	isRemoteMode: boolean;
	cookieHeader: string | undefined;
	authorizationHeader: string | undefined;
}): "allowed" | "rejected" {
	const passcodeActive = input.isRemoteMode && isPasscodeEnabled();
	if (passcodeActive) {
		const sessionToken = extractSessionTokenFromCookie(input.cookieHeader);
		const sessionAuth = sessionToken !== null && validateSession(sessionToken);
		const bearerToken = extractBearerToken(input.authorizationHeader);
		const internalAuth = bearerToken !== null && validateInternalToken(bearerToken);
		if (!sessionAuth && !internalAuth) return "rejected";
	}
	return "allowed";
}

afterEach(() => {
	vi.restoreAllMocks();
	generatePasscode();
	delete process.env[INTERNAL_TOKEN_ENV];
});

describe("Internal CLI auth token", () => {
	it("generates a 64-char hex token", () => {
		expect(generateInternalToken()).toMatch(/^[0-9a-f]{64}$/);
	});

	it("getInternalToken() returns the generated token", () => {
		const token = generateInternalToken();
		expect(getInternalToken()).toBe(token);
	});

	it("sets the env var for child process inheritance", () => {
		const token = generateInternalToken();
		expect(process.env[INTERNAL_TOKEN_ENV]).toBe(token);
	});

	it("regenerating produces a different value", () => {
		const t1 = generateInternalToken();
		const t2 = generateInternalToken();
		expect(t1).not.toBe(t2);
		expect(getInternalToken()).toBe(t2);
	});

	it("validates a correct token", () => {
		const token = generateInternalToken();
		expect(validateInternalToken(token)).toBe(true);
	});

	it("rejects an incorrect token", () => {
		generateInternalToken();
		expect(validateInternalToken("wrong")).toBe(false);
	});

	it("rejects empty string", () => {
		generateInternalToken();
		expect(validateInternalToken("")).toBe(false);
	});

	it("rejects a token with wrong length", () => {
		generateInternalToken();
		expect(validateInternalToken("abc")).toBe(false);
		expect(validateInternalToken("a".repeat(128))).toBe(false);
	});

	it("returns false when no token was generated", () => {
		expect(validateInternalToken("anything")).toBe(false);
	});

	it("validates only the latest token after regeneration", () => {
		generatePasscode();
		const old = generateInternalToken();
		const cur = generateInternalToken();
		expect(validateInternalToken(old)).toBe(false);
		expect(validateInternalToken(cur)).toBe(true);
	});
});

describe("extractBearerToken", () => {
	it("extracts token from well-formed header", () => {
		expect(extractBearerToken("Bearer abc123")).toBe("abc123");
	});

	it("is case-insensitive on scheme", () => {
		expect(extractBearerToken("bearer abc")).toBe("abc");
		expect(extractBearerToken("BEARER abc")).toBe("abc");
	});

	it("returns null for undefined", () => {
		expect(extractBearerToken(undefined)).toBeNull();
	});

	it("returns null for non-Bearer scheme", () => {
		expect(extractBearerToken("Basic abc")).toBeNull();
	});

	it("returns null when token part is missing", () => {
		expect(extractBearerToken("Bearer ")).toBeNull();
		expect(extractBearerToken("Bearer")).toBeNull();
	});
});

describe("Passcode lifetime", () => {
	it("keeps passcodes valid beyond the old 24h window", () => {
		const nowSpy = vi.spyOn(Date, "now");
		nowSpy.mockReturnValue(1_000_000);
		const passcode = generatePasscode();
		nowSpy.mockReturnValue(1_000_000 + 25 * 60 * 60 * 1000);
		expect(validatePasscode(passcode)).toBe(true);
	});
});

describe("HTTP passcode gate with internal token", () => {
	it("allows API request with valid internal bearer token", () => {
		generatePasscode();
		const token = generateInternalToken();
		expect(
			runHttpGate({
				isRemoteMode: true,
				cookieHeader: undefined,
				authorizationHeader: `Bearer ${token}`,
				pathname: "/api/trpc",
			}),
		).toBe("allowed");
	});

	it("rejects API request with invalid bearer token", () => {
		generatePasscode();
		generateInternalToken();
		expect(
			runHttpGate({
				isRemoteMode: true,
				cookieHeader: undefined,
				authorizationHeader: "Bearer wrong",
				pathname: "/api/trpc",
			}),
		).toBe("rejected");
	});

	it("allows API request with valid session cookie", () => {
		generatePasscode();
		generateInternalToken();
		const session = issueSession();
		expect(
			runHttpGate({
				isRemoteMode: true,
				cookieHeader: `kanban_session=${session}`,
				authorizationHeader: undefined,
				pathname: "/api/trpc",
			}),
		).toBe("allowed");
	});

	it("rejects API request with no auth in remote mode", () => {
		generatePasscode();
		generateInternalToken();
		expect(
			runHttpGate({
				isRemoteMode: true,
				cookieHeader: undefined,
				authorizationHeader: undefined,
				pathname: "/api/trpc",
			}),
		).toBe("rejected");
	});

	it("allows API request without auth when NOT in remote mode", () => {
		generatePasscode();
		generateInternalToken();
		expect(
			runHttpGate({
				isRemoteMode: false,
				cookieHeader: undefined,
				authorizationHeader: undefined,
				pathname: "/api/trpc",
			}),
		).toBe("allowed");
	});

	it("allows non-API path even without auth in remote mode", () => {
		generatePasscode();
		generateInternalToken();
		expect(
			runHttpGate({
				isRemoteMode: true,
				cookieHeader: undefined,
				authorizationHeader: undefined,
				pathname: "/assets/app.js",
			}),
		).toBe("allowed");
	});

	it("allows when passcode is disabled", () => {
		disablePasscode();
		expect(
			runHttpGate({
				isRemoteMode: true,
				cookieHeader: undefined,
				authorizationHeader: undefined,
				pathname: "/api/trpc",
			}),
		).toBe("allowed");
	});
});

describe("WS upgrade gate with internal token", () => {
	it("allows upgrade with valid bearer token", () => {
		generatePasscode();
		const token = generateInternalToken();
		expect(
			runWsUpgradeGate({
				isRemoteMode: true,
				cookieHeader: undefined,
				authorizationHeader: `Bearer ${token}`,
			}),
		).toBe("allowed");
	});

	it("rejects upgrade with invalid bearer token", () => {
		generatePasscode();
		generateInternalToken();
		expect(
			runWsUpgradeGate({
				isRemoteMode: true,
				cookieHeader: undefined,
				authorizationHeader: "Bearer wrong",
			}),
		).toBe("rejected");
	});

	it("allows upgrade with valid session cookie", () => {
		generatePasscode();
		generateInternalToken();
		const session = issueSession();
		expect(
			runWsUpgradeGate({
				isRemoteMode: true,
				cookieHeader: `kanban_session=${session}`,
				authorizationHeader: undefined,
			}),
		).toBe("allowed");
	});

	it("rejects upgrade with no auth in remote mode", () => {
		generatePasscode();
		generateInternalToken();
		expect(
			runWsUpgradeGate({
				isRemoteMode: true,
				cookieHeader: undefined,
				authorizationHeader: undefined,
			}),
		).toBe("rejected");
	});
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

// ---------------------------------------------------------------------------
// Mock Electron
// ---------------------------------------------------------------------------

const { showMessageBoxMock } = vi.hoisted(() => ({
	showMessageBoxMock: vi.fn().mockResolvedValue({ response: 0 }),
}));

vi.mock("electron", () => ({
	dialog: { showMessageBox: showMessageBoxMock },
}));

import { type OAuthRelayDeps, relayOAuthCallback } from "../src/oauth-relay.js";
import type { BrowserWindow } from "electron";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function fakeWindow(destroyed = false): BrowserWindow {
	return { isDestroyed: () => destroyed } as unknown as BrowserWindow;
}

function makeDeps(overrides?: Partial<OAuthRelayDeps>): OAuthRelayDeps {
	return {
		fetch: overrides?.fetch ?? vi.fn().mockResolvedValue({ ok: true }),
		getMainWindow: overrides?.getMainWindow ?? (() => fakeWindow()),
	};
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe("relayOAuthCallback", () => {
	beforeEach(() => { vi.clearAllMocks(); vi.useFakeTimers(); });
	afterEach(() => { vi.useRealTimers(); });

	it("succeeds on first attempt without retrying", async () => {
		const fetchMock = vi.fn().mockResolvedValue({ ok: true });
		const deps = makeDeps({ fetch: fetchMock });
		const p = relayOAuthCallback("http://localhost:3000/cb", deps);
		await vi.runAllTimersAsync();
		await p;
		expect(fetchMock).toHaveBeenCalledTimes(1);
		expect(fetchMock).toHaveBeenCalledWith("http://localhost:3000/cb");
		expect(showMessageBoxMock).not.toHaveBeenCalled();
	});


	it("retries on fetch failure and succeeds on second attempt", async () => {
		const fetchMock = vi.fn()
			.mockRejectedValueOnce(new Error("ECONNREFUSED"))
			.mockResolvedValueOnce({ ok: true });
		const deps = makeDeps({ fetch: fetchMock });
		const p = relayOAuthCallback("http://localhost:3000/cb", deps);
		await vi.runAllTimersAsync();
		await p;
		expect(fetchMock).toHaveBeenCalledTimes(2);
		expect(showMessageBoxMock).not.toHaveBeenCalled();
	});

	it("retries on non-ok response and succeeds on second attempt", async () => {
		const fetchMock = vi.fn()
			.mockResolvedValueOnce({ ok: false, status: 503 })
			.mockResolvedValueOnce({ ok: true });
		const deps = makeDeps({ fetch: fetchMock });
		const p = relayOAuthCallback("http://localhost:3000/cb", deps);
		await vi.runAllTimersAsync();
		await p;
		expect(fetchMock).toHaveBeenCalledTimes(2);
		expect(showMessageBoxMock).not.toHaveBeenCalled();
	});

	it("retries up to 2 times (3 total attempts) before exhausting", async () => {
		const fetchMock = vi.fn().mockRejectedValue(new Error("ECONNREFUSED"));
		const deps = makeDeps({ fetch: fetchMock });
		const p = relayOAuthCallback("http://localhost:3000/cb", deps);
		await vi.runAllTimersAsync();
		await p;
		expect(fetchMock).toHaveBeenCalledTimes(3);
	});

	it("shows dialog after exhausting all retries", async () => {
		const fetchMock = vi.fn().mockRejectedValue(new Error("ECONNREFUSED"));
		const window = fakeWindow();
		const deps = makeDeps({ fetch: fetchMock, getMainWindow: () => window });
		const p = relayOAuthCallback("http://localhost:3000/cb", deps);
		await vi.runAllTimersAsync();
		await p;
		expect(showMessageBoxMock).toHaveBeenCalledTimes(1);
		expect(showMessageBoxMock).toHaveBeenCalledWith(window, {
			type: "warning",
			title: "OAuth Callback Failed",
			message: "The authentication callback could not be delivered. Please try again.",
			buttons: ["OK"],
		});
	});

	it("shows dialog when all responses are non-ok", async () => {
		const fetchMock = vi.fn().mockResolvedValue({ ok: false, status: 500 });
		const deps = makeDeps({ fetch: fetchMock });
		const p = relayOAuthCallback("http://localhost:3000/cb", deps);
		await vi.runAllTimersAsync();
		await p;
		expect(fetchMock).toHaveBeenCalledTimes(3);
		expect(showMessageBoxMock).toHaveBeenCalledTimes(1);
	});

	it("does not show dialog when mainWindow is null", async () => {
		const fetchMock = vi.fn().mockRejectedValue(new Error("ECONNREFUSED"));
		const deps = makeDeps({ fetch: fetchMock, getMainWindow: () => null });
		const p = relayOAuthCallback("http://localhost:3000/cb", deps);
		await vi.runAllTimersAsync();
		await p;
		expect(fetchMock).toHaveBeenCalledTimes(3);
		expect(showMessageBoxMock).not.toHaveBeenCalled();
	});

	it("does not show dialog when mainWindow is destroyed", async () => {
		const fetchMock = vi.fn().mockRejectedValue(new Error("ECONNREFUSED"));
		const deps = makeDeps({ fetch: fetchMock, getMainWindow: () => fakeWindow(true) });
		const p = relayOAuthCallback("http://localhost:3000/cb", deps);
		await vi.runAllTimersAsync();
		await p;
		expect(fetchMock).toHaveBeenCalledTimes(3);
		expect(showMessageBoxMock).not.toHaveBeenCalled();
	});

	it("respects custom retry count", async () => {
		const fetchMock = vi.fn().mockRejectedValue(new Error("ECONNREFUSED"));
		const deps = makeDeps({ fetch: fetchMock });
		const p = relayOAuthCallback("http://localhost:3000/cb", deps, 0);
		await vi.runAllTimersAsync();
		await p;
		expect(fetchMock).toHaveBeenCalledTimes(1);
		expect(showMessageBoxMock).toHaveBeenCalledTimes(1);
	});

	it("delays 1 second between retry attempts", async () => {
		const fetchMock = vi.fn()
			.mockRejectedValueOnce(new Error("fail"))
			.mockResolvedValueOnce({ ok: true });
		const deps = makeDeps({ fetch: fetchMock });
		const p = relayOAuthCallback("http://localhost:3000/cb", deps);
		// After first failed attempt, second should not have been called yet
		await vi.advanceTimersByTimeAsync(0);
		expect(fetchMock).toHaveBeenCalledTimes(1);
		// Advance past the 1s delay
		await vi.advanceTimersByTimeAsync(1_000);
		await p;
		expect(fetchMock).toHaveBeenCalledTimes(2);
	});
});

import { spawnSync } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import { searchWorkspaceFiles } from "../../src/workspace/search-workspace-files";
import { createGitTestEnv } from "../utilities/git-env";
import { createTempDir } from "../utilities/temp-dir";

function runGit(cwd: string, args: string[]): string {
	const result = spawnSync("git", args, {
		cwd,
		encoding: "utf8",
		env: createGitTestEnv(),
	});
	if (result.status !== 0) {
		throw new Error(result.stderr || result.stdout || `git ${args.join(" ")} failed`);
	}
	return result.stdout.trim();
}

function initRepository(path: string): void {
	runGit(path, ["init", "-q"]);
	runGit(path, ["config", "user.name", "Test User"]);
	runGit(path, ["config", "user.email", "test@example.com"]);
}

function commitAll(cwd: string, message: string): string {
	runGit(cwd, ["add", "."]);
	runGit(cwd, ["commit", "-qm", message]);
	return runGit(cwd, ["rev-parse", "HEAD"]);
}

describe.sequential("search workspace files runtime", () => {
	it("finds modified tracked files with non-ASCII paths using UTF-8 query text", async () => {
		const { path: repoPath, cleanup } = createTempDir("kanban-search-files-nonascii-tracked-");
		try {
			initRepository(repoPath);
			const directory = "提出書類";
			const fileName = "設計書.md";
			const relativePath = `${directory}/${fileName}`;
			mkdirSync(join(repoPath, directory), { recursive: true });
			writeFileSync(join(repoPath, relativePath), "first\n", "utf8");
			commitAll(repoPath, "add non-ascii tracked file");
			writeFileSync(join(repoPath, relativePath), "updated\n", "utf8");

			const results = await searchWorkspaceFiles(repoPath, "提出", 20);

			expect(results).toHaveLength(1);
			expect(results[0]).toEqual({
				path: relativePath,
				name: fileName,
				changed: true,
			});
		} finally {
			cleanup();
		}
	});

	it("finds untracked files with non-ASCII paths using UTF-8 query text", async () => {
