	return {
		record: {
			sessionId: "task-1-abc123",
			source: "core" as ClinePersistedTaskSessionSnapshot["record"]["source"],
			status: "completed",
			startedAt: "2026-03-17T10:00:00.000Z",
			updatedAt: "2026-03-17T10:05:00.000Z",
			interactive: true,
			provider: "anthropic",
			model: "claude-sonnet-4-6",
			cwd: "/tmp/worktree",
			workspaceRoot: "/tmp/repo",
			enableTools: true,
